"""Migrated Meridian CRM 4.2 order validation rules."""

from decimal import Decimal
from typing import Any


def _value(row: dict | None, column: str) -> Any:
    if row is None:
        return ""
    return row.get(column, "")


def _number(value: Any) -> Decimal:
    """Apply legacy numeric coercion: an empty value is numeric zero."""
    if value is None or value == "":
        return Decimal(0)
    return Decimal(str(value))


def _lookup(
    tables: dict | None,
    table_name: str,
    key_column: str,
    key_value: Any,
    output_column: str,
) -> Any:
    """Implement legacy LOOKUP, including live-row filtering and first-match order."""
    if tables is None:
        return ""

    for row in tables.get(table_name, []):
        if row.get("DEL_FLG", "") == "Y":
            continue
        if row.get(key_column, "") == key_value:
            return row.get(output_column, "")

    return ""


def _error(code: str, message: str) -> dict:
    return {"code": code, "message": message, "severity": "BLOCK"}


def validate(
    record: dict,
    old: dict | None = None,
    event: str = "INSERT",
    tables: dict | None = None,
    table: str = "ORD_HEADER",
) -> list[dict]:
    """Validate an order header or order line using the migrated VRL rules."""
    errors: list[dict] = []

    if table == "ORD_HEADER":
        # ORD-001: ON ORD_HEADER WHEN INSERT,UPDATE
        if event in ("INSERT", "UPDATE"):
            disc_pct = _number(_value(record, "DISC_PCT"))
            if not (disc_pct >= Decimal(0) and disc_pct <= Decimal(100)):
                errors.append(_error("E5001", "Discount out of range"))

        # ORD-002: ON ORD_HEADER WHEN UPDATE
        if event == "UPDATE":
            disc_pct = _number(_value(record, "DISC_PCT"))
            owner_uid = _value(record, "OWNER_UID")
            role_id = _lookup(
                tables, "USR_MASTER", "USR_ID", owner_uid, "ROLE_ID"
            )
            if disc_pct > Decimal(20) and role_id != "MGR" and role_id != "ADMIN":
                errors.append(
                    _error(
                        "E5002",
                        "Discount over 20 percent requires manager role",
                    )
                )

        # ORD-003: ON ORD_HEADER WHEN UPDATE
        if event == "UPDATE":
            old_status = _value(old, "STAT_CD")
            status = _value(record, "STAT_CD")
            if old_status == "I" and status != "I" and status != "X":
                errors.append(
                    _error("E5003", "Invoiced order can only be cancelled")
                )

    elif table == "ORD_LINE":
        # ORD-004: ON ORD_LINE WHEN INSERT,UPDATE
        if event in ("INSERT", "UPDATE"):
            qty = _number(_value(record, "QTY"))
            if not qty > Decimal(0):
                errors.append(_error("E5004", "Quantity must be positive"))

        # ORD-005: ON ORD_LINE WHEN INSERT
        if event == "INSERT":
            product_id = _value(record, "PROD_ID")
            active_flag = _lookup(
                tables, "PROD_MASTER", "PROD_ID", product_id, "ACTIVE_FLG"
            )
            if active_flag != "Y":
                errors.append(_error("E5005", "Product not active"))

    return errors


def is_blocked(errors: list[dict]) -> bool:
    """Return whether any collected validation failure is blocking."""
    return any(error.get("severity") == "BLOCK" for error in errors)
